mapper.select:
select a.task_id, b.device_id, b.instance_id, e.real_code, d.device_name, f.instance_name, g.cruise_type, h.dict_note as cruise_type_name, g.result_num, g.state, j.dict_note as data_state, b.cruise_time, g.evaluation_state, k.dict_note as evaluation_state_name, g.check_user, g.check_date, g.picpath, g.identify_result, g.identify_state, g.person_check FROM ( t_std_device d LEFT JOIN t_std_device_attr e ON d.device_id = e.device_id ) LEFT JOIN ( ( ( t_cruise_task_result_detail b LEFT JOIN t_cruise_point_attr f ON f.instance_id = b.instance_id ) LEFT JOIN t_cruise_result a ON a.task_result_id = b.task_result_id ) LEFT JOIN ( ( ( t_cruise_data_result g LEFT JOIN t_dict_business h ON h.dict_code = g.cruise_type ) LEFT JOIN t_dict_business k ON k.dict_code = g.evaluation_state ) LEFT JOIN t_dict_business j ON j.dict_code = g.state ) ON g.cruise_result_id = b.cruise_result_id ) ON d.device_id = b.device_id WHERE 1 = 1 and a.task_id = #{taskId,jdbcType=BIGINT} and a.execute_time = #{executeTime,jdbcType=TIMESTAMP}
and d.device_name like concat ('%',#{deviceName,jdbcType=VARCHAR},'%')
and g.cruise_type = #{cruiseType, jdbcType=INTEGER}
and g.state = #{state, jdbcType=INTEGER}

mapper.update:
update t_cruise_result a 
a.task_result_id = #{taskResultId, jdbcType=VARCHAR},
a.check_user = #{checkUserName, jdbcType=VARCHAR},
a.check_date = #{checkDate, jdbcType=TIMESTAMP}

where a.task_result_id = #{taskResultId, jdbcType=VARCHAR}
